    "title": "小米SU9 LUX曝光，定位行政豪华轿车",
    "link": "https://finance.sina.com.cn/tech/csj/2026-10-19/doc-inivueup6920307.shtml",
    "pub_date": "2026-10-19 19:11:39",
    "author": "",
    "description": "（来源：科技头版） 雷军：超豪华车市场的大门已经对小米打开了。 出品 | 科技头版 作者 | 松涛 小米的一个新商标，让行政豪华轿车市场又多了一个新话题。 公开商标查询信息显示，小米公司近期申请的“XIAOMI SU9 LUX”商标，目前已经完成注册公告。查询页将其状态列为“已注册”，所属类别为第12类，包含汽车等运输工具。 SU9这个名字，再加上后缀取自英文“Luxury”（奢华）的“LUX”，很快勾起了外界对小米行政轿车的期待。此前…",
