    "content": "36氪获悉，10月19日，腾讯云发布通知：接.com域名注册局Verisign通知，.com域名注册局批发价格将于2026年11月1日起在全球范围内上调。受上游成本变动影响，腾讯云将同步调整.com域名的销售价格。.com后缀的注册、续费、转入（转入操作按续费一年计）价格上调，赎回价格维持不变；其他域名后缀价格也不受影响。"
