    "author": "",
    "description": "36氪获悉，据天眼查显示，小米汽车科技有限公司申请的“增程器、动力总成及车辆”实用新型专利于10月16日获授权，目前处于有效状态，申请日为2025年10月27日。专利摘要记载，该增程器将发动机与电机总成并排布置，发电机与电机控制器则沿平行于发动机轴线的方向排列。该布局可以至少不额外增加增程器沿发动机轴线方向的尺寸：发动机纵置时，减少增程器的纵向占用空间；横置时，减少横向占用空间。电机控制器与发电机共用发动机轴线方向的空间，以提高空间利用…",
    "content": "36氪获悉，据天眼查显示，小米汽车科技有限公司申请的“增程器、动力总成及车辆”实用新型专利于10月16日获授权，目前处于有效状态，申请日为2025年10月27日。专利摘要记载，该增程器将发动机与电机总成并排布置，发电机与电机控制器则沿平行于发动机轴线的方向排列。该布局可以至少不额外增加增程器沿发动机轴线方向的尺寸：发动机纵置时，减少增程器的纵向占用空间；横置时，减少横向占用空间。电机控制器与发电机共用发动机轴线方向的空间，以提高空间利用率。"
