    "description": "AI假冒名人带货，平台真看不见？ 近期，演员吴越、乒乓球名将邓亚萍相继痛斥不法商家利用AI换脸、声音克隆技术盗用二人形象，合成短视频推销产品。他们的公开发声，也将AI仿冒名人带货的灰色产业链再次推到舆论前台。 AI数字人带货本身并非洪水猛兽，这项技术可以降低直播门槛、提升传播效率。但问题在于，部分不法商家在根本没有得到授权的前提下，仅凭少量照片与音频素材，就能低成本批量合成名人出镜带货视频，这是在借用名人的影响力牟利，更可能触碰法律红线…",
    "content": "AI假冒名人带货，平台真看不见？ 近期，演员吴越、乒乓球名将邓亚萍相继痛斥不法商家利用AI换脸、声音克隆技术盗用二人形象，合成短视频推销产品。他们的公开发声，也将AI仿冒名人带货的灰色产业链再次推到舆论前台。 AI数字人带货本身并非洪水猛兽，这项技术可以降低直播门槛、提升传播效率。但问题在于，部分不法商家在根本没有得到授权的前提下，仅凭少量照片与音频素材，就能低成本批量合成名人出镜带货视频，这是在借用名人的影响力牟利，更可能触碰法律红线。 事实上，未经许可复刻他人形象用于商业推广，既侵犯肖像权、声音权，还涉嫌虚假宣…"
