    "title": "阳澄湖大闸蟹协会回应“大闸蟹行情崩盘”：与真实供需格局不符",
    "link": "https://m.thepaper.cn/newsDetail_forward_34281401",
    "pub_date": "2026-10-19 18:40:10",
    "author": "",
