    "description": "如果你笔记本高音好， 配了个低音炮，可以高音走笔记本，低音走低音炮。 把 Mac 的内置喇叭和外接音箱当成一套声学系统来用：不是简单地把同一路全频信号同时推给两个设备，而是先分频再分别输出 —— 内置喇叭只唱中高频，外接音箱只负责低频，再用延迟补偿把两条链路对齐。 github.com/peterxulove/multispeaker-macos",
