    "content": "今年前三季度，服务业对中国经济增长的贡献率达66.3%，同比提高5.6个百分点，中国国家统计局称，服务业是拉动经济增长的主引擎。 综合中新社、第一财经等报道，中国国家统计局星期一（10月19日）公布数据显示，前三季度，服务业增加值同比增长5.2%；9月份，服务业商务活动指数为50.2%，比上月上升0.9个百分点。 国家统计局副局长毛盛勇星期一指出，今年前三季度，服务业规模扩大、贡献提升，服务业增加值达到62.8万亿元（人民币，12万亿新元），快于同期经济增速0.6个百分点，占中国国内生产总值的比重达到58.7%，同…"
