    "description": "新华社西宁10月19日电（记者王金金、柳泽兴）烟火缭绕、人声鼎沸。走进青海省西宁市城东区下南关街，飘香的美食、热闹的摊位、往来的游人令人眼花缭乱，热闹气息扑面而来。 作为唐蕃古道河湟段重要的商贸驿站，下南关街自古便是中原与高原物资互通、商旅停歇的关键节点。昔日古道驼铃声声，今朝市井烟火繁盛，这条百年老街正在古今交融中焕发生机。 西宁市城东区下南关街的美食。新华社发 缓步走入下南关街巷，平整的摊位、精致的文化景观、错落的商铺让人耳目一新。…",
    "content": "新华社西宁10月19日电（记者王金金、柳泽兴）烟火缭绕、人声鼎沸。走进青海省西宁市城东区下南关街，飘香的美食、热闹的摊位、往来的游人令人眼花缭乱，热闹气息扑面而来。 作为唐蕃古道河湟段重要的商贸驿站，下南关街自古便是中原与高原物资互通、商旅停歇的关键节点。昔日古道驼铃声声，今朝市井烟火繁盛，这条百年老街正在古今交融中焕发生机。 西宁市城东区下南关街的美食。新华社发 缓步走入下南关街巷，平整的摊位、精致的文化景观、错落的商铺让人耳目一新。 下南关街始于明代万历年间，为防范外敌侵扰、守护关厢商贾，明军修筑关厢城墙。城防…"
