    "content": "国家统计局10月19日发布数据显示，初步核算，前三季度我国国内生产总值（GDP）1071071亿元，按不变价格计算，同比增长4.6%。 前三季度，全国规模以上工业增加值同比增长5.3%，服务业增加值同比增长5.2%。 前三季度，社会消费商品和服务零售总额同比增长2.6%；知识产权产品投资同比增长9.3%；货物进出口总额399399亿元，同比增长18.8%。 居民消费价格温和上涨，就业形势总体稳定，居民收入平稳增长。前三季度，全国居民消费价格（CPI）同比上涨0.9%，工业生产者出厂价格同比上涨2.3%；全国城镇调查…"
