    "content": "新华社北京10月19日电 美国特朗普政府近期放松针对俄罗斯能源出口的制裁，一些共和党人着眼国会中期选举接连发声，反对政府对俄展露友好姿态。18日公布的一项最新民调显示，民主党的中期选举优势有所上升。 共和党候选人反对 本月早些时候，特朗普政府宣布放松对俄柴油贸易制裁，并称已与俄方达成由俄向美及全球市场供应柴油的协议。分析人士认为，特朗普政府“松绑”对俄制裁主要是为了在11月3日中期选举前平抑能源价格、争取选民支持，但这与美国政界近些年来反俄挺乌的“政治正确”相悖，且抑制油价效果存疑。 10月16日，在美国缅因州班戈…"
