    "title": "《关于加快推进科技兴商的意见》是为适应消费新趋势",
    "link": "http://www.news.cn/20261019/b7056d313c714e4fa91584e1c4cf9f47/c.html",
    "pub_date": "2026-10-19 17:20:21",
