    "content": "新华社北京10月19日电（记者胡了然）为纪念中国工农红军长征胜利90周年，弘扬伟大长征精神，中央档案馆向社会集中开放一批长征专题档案，共计5000余件。 此次开放的长征专题档案，主要包括1934年10月至1936年10月期间，毛泽东、周恩来、朱德等老一辈革命家起草、签发的指示文稿与作战电文，长征途中重要会议文献和重大战役战斗电报、军事作战部署，革命宣言、工作报告、会议材料、行军记录、各类通知命令以及党创办发行的红色报刊等，种类丰富、覆盖面广。其中，林伯渠在长征途中手写的长征日记原件、由中国共产党上海中央局创办的《捷…"
