    "content": "中国央行行长潘功胜宣布将推动系列政策措施出台，包括设立应对非银机构大额赎回的流动性支持工具、扩大常备借贷便利的适用机构范围。 据金融界、央视新闻报道，潘功胜星期一（10月19日）在2026金融街论坛年会开幕式上宣布，即将推动出台的一系列政策措施。 潘功胜宣布，将会同金融监管总局、中国证监会设立应对非银机构大额赎回的流动性支持工具。目的是建立债券市场稳定机制，构成人民银行宏观审慎管理的一项新工具。 央行也将扩大常备借贷便利的适用机构范围，进一步纳入境内外资法人银行，同时明确全国性银行适用同样的操作安排，实现对境内存款…"
